namespace Sunplus.Agent.Model.Services
{
    using System;
    using Fanex.Logging.Extensions.Web;
    using ONEbook.UM;
    using ONEbook.UM.Models;
    using ONEbook.UM.Services;

    public class MaintenanceService
    {
        private static readonly IMaintenanceService _maintenanceService = new ONEbook.UM.Services.MaintenanceService(
            UMClientManager.RestClient,
            UMClientManager.CacheService,
            UMClientManager.UMClientConfigs,
            UMClientManager.HttpContext);

        public static bool IsUnderMaintenance()
        {
            try
            {
                if (_maintenanceService.IsUnderMaintenance())
                {
                    return true;
                }
            }
            catch (Exception ex)
            {
                ExceptionHandler.Handle(ex);
            }

            return false;
        }

        public static bool IsUnderMaintenance(out string startTime, out string endTime)
        {
            try
            {
                if (_maintenanceService.IsUnderMaintenance())
                {
                    UnderMaintenanceTime underMaintenanceTime = _maintenanceService.GetUnderMaintenanceTime();
                    startTime = underMaintenanceTime.From;
                    endTime = underMaintenanceTime.To;
                    return true;
                }
            }
            catch (Exception ex)
            {
                ExceptionHandler.Handle(ex);
            }

            startTime = endTime = null;
            return false;
        }
    }
}